// === Tab: mySketch ===

let num = 1000;
let points = new Array(num).fill(0).map(e=> {
return {
  vx:0,
  vy:0,
  ax:0,
  ay:0,
  x:0,
  y:0,
}
})
let settings = {
mag:10,
radius:1,
damp:0.95
}

function setup(){
  createCanvas(windowWidth,windowHeight);
  noStroke(); 
  fill(0);
  ellipseMode(RADIUS);
  background(0);
  blendMode(ADD);

  for(let i =0; i< num; i++){
    points[i].x= random(width);
    points[i].y= random(height);
  }
	console.log(points)
  fill(0,0,0);
  rect(0,0,width,height);

}


function draw(){

  // go through the points
  for(let i=0; i<num; i++){

    let pt = points[i]
    if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
		let distance = dist(touchX, touchY, pt.x, pt.y); 
    if(distance > 3){ 
      pt.ax = settings.mag* (touchX - pt.x) / (distance * distance); 
      pt.ay = settings.mag * (touchY - pt.y) / (distance * distance);
    }

		}
		 pt.vx+= pt.ax 
    pt.vy+= pt.ay 
    pt.vx = pt.vx*settings.damp;
    pt.vy = pt.vy*settings.damp;
    pt.x += pt.vx;  
    pt.y += pt.vy;  
    let absSpeed = dist(0,0,pt.vx,pt.vy); 
    let r = map(absSpeed, 0, 5, 128, 255); 
    let g = map(absSpeed, 0,5, 64, 255);
    let b = map(absSpeed, 0,5, 128, 255);
    fill(r, g, b, 32);
    ellipse(pt.x,pt.y,settings.radius,settings.radius);
  }


}

